#include <stdio.h>

/* teste do desafio o-gritador — counter_protocol (03-tdd 3.9.3).
   Quem DIGITA e o teste: fopen/fprintf escrevem num arquivo o que o aluno
   digitaria e o freopen troca o stdin por esse arquivo; a captura do
   stdout acontece dentro do proprio cenario (freopen + fflush, sem
   fclose no stdout). Duas palavras de letras diferentes: a saida tem de
   vir da troca gaveta por gaveta, nunca de um literal fixo no codigo. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void oGritador(void);

SM_TEST(a_palavra_ana_gritada) {
    FILE *digitado = fopen("sm_entrada_1.tmp", "w");
    fprintf(digitado, "ana\n");
    fclose(digitado);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    oGritador();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("ana gritado", linha, "ANA\n",
              "cada uma das tres letras perdeu 32 e virou maiuscula");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e so a palavra gritada: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(a_palavra_bola_gritada) {
