#include <stdio.h>

void oGritador(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    for (int i = 0; palavra[i] != '\0'; i++) {
        palavra[i] = palavra[i] - 32;
    }
    printf("%s\n", palavra);
}
